def add_memory(content, metadata=None, source=None, **_extra):
    import json, os, datetime, hashlib, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0265000" if __import__("os").path.isdir("./environment_mix/0265000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_dt().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _utc_day_key(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).date().isoformat()

    def _gen_id(prefix, rows):
        # pseudo-ULID-ish with time component + counter
        ts = int(_now_dt().timestamp() * 1000)
        base = f"{prefix}_{ts:x}"
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        if base not in existing:
            return base
        c = 1
        while f"{base}_{c}" in existing:
            c += 1
        return f"{base}_{c}"

    t0 = time.time()
    endpoint = "add-memory"

    # additionalProperties=false
    if _extra:
        return _err("VALIDATION_ERROR", "Unknown fields provided.", unknown_fields=sorted(list(_extra.keys())))

    if not isinstance(content, str):
        return _err("VALIDATION_ERROR", "Field 'content' must be a string.", field="content")
    if content.strip() == "":
        return _err("VALIDATION_ERROR", "Field 'content' must be non-empty.", field="content")
    if not (1 <= len(content) <= 65535):
        return _err("VALIDATION_ERROR", "Field 'content' length must be between 1 and 65535.", field="content")

    if metadata is not None and not isinstance(metadata, dict):
        return _err("VALIDATION_ERROR", "Field 'metadata' must be an object.", field="metadata")

    if source is not None and not isinstance(source, str):
        return _err("VALIDATION_ERROR", "Field 'source' must be a string.", field="source")

    api_keys = _load("api_keys.json")
    memories = _load("memories.json")
    searches = _load("memory_searches.json")

    # Resolve ambient auth: choose an active key that can write (daily_add_limit not exceeded)
    now = _now_dt()
    today = _utc_day_key(now)

    # Precompute counts per key for today based on created_at in memories
    counts = {}
    for m in memories:
        if not isinstance(m, dict):
            continue
        ak = m.get("api_key_id")
        ca = _parse_iso(m.get("created_at"))
        if ak and ca:
            if _utc_day_key(ca) == today:
                counts[ak] = counts.get(ak, 0) + 1

    caller_key = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        lim = k.get("daily_add_limit")
        if not isinstance(lim, int) or lim < 0:
            continue
        if counts.get(k.get("id"), 0) < lim:
            caller_key = k
            break

    if caller_key is None:
        # If there is at least one active key, it's a quota issue; otherwise unauthorized.
        any_active = any(isinstance(k, dict) and k.get("status") == "active" for k in api_keys)
        code = "QUOTA_EXCEEDED" if any_active else "UNAUTHORIZED"
        msg = "Daily add-memory quota exceeded." if any_active else "No active API key available for this request."
        # Record failed search/audit row
        sid = _gen_id("mem0_srch", searches)
        now_iso = _now_iso()
        searches.append({
            "id": sid,
            "api_key_id": (caller_key or {}).get("id") if caller_key else (next((k.get("id") for k in api_keys if isinstance(k, dict)), None)),
            "query_text": None,
            "query_payload": {"endpoint": endpoint, "content_sha256": hashlib.sha256(content.encode("utf-8")).hexdigest(), "quota_day": today},
            "top_k": 1,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "status": "failed",
            "error_message": "quota_exceeded" if code == "QUOTA_EXCEEDED" else "unauthorized",
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("memory_searches.json", searches)
        return _err(code, msg)

    api_key_id = caller_key.get("id")

    # Reject non-active keys per business rules
    if caller_key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active.", api_key_id=api_key_id)

    # Deduplication by (api_key_id, content_sha256) where status != 'deleted'
    digest = hashlib.sha256(content.encode("utf-8")).hexdigest()
    existing = None
    for m in memories:
        if not isinstance(m, dict):
            continue
        if m.get("api_key_id") == api_key_id and m.get("content_sha256") == digest and m.get("status") != "deleted":
            existing = m
            break

    now_iso = _now_iso()
    if existing is not None:
        # audit/usage record: represent as a search row (since no dedicated request log exists)
        sid = _gen_id("mem0_srch", searches)
        searches.append({
            "id": sid,
            "api_key_id": api_key_id,
            "query_text": None,
            "query_payload": {"endpoint": endpoint, "dedup": True, "returned_existing_id": existing.get("id")},
            "top_k": 1,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "status": "succeeded",
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("memory_searches.json", searches)

        # update last_used_at
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_id:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break
        _save("api_keys.json", api_keys)

        return {"memory": existing}

    mem_id = _gen_id("mem0_mem", memories)
    row = {
        "id": mem_id,
        "api_key_id": api_key_id,
        "source": source,
        "content": content,
        "metadata": metadata if metadata is not None else None,
        "content_sha256": digest,
        "embedding": None,
        "embedding_model": None,
        "status": "active",
        "archived_at": None,
        "deleted_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    memories.append(row)
    _save("memories.json", memories)

    # audit/usage record
    sid = _gen_id("mem0_srch", searches)
    searches.append({
        "id": sid,
        "api_key_id": api_key_id,
        "query_text": None,
        "query_payload": {"endpoint": endpoint, "created_memory_id": mem_id},
        "top_k": 1,
        "latency_ms": max(0, int((time.time() - t0) * 1000)),
        "status": "succeeded",
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso
    })
    _save("memory_searches.json", searches)

    # update last_used_at
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    return {"memory": row}

def search_memories(query, top_k=None, filter=None, **_extra):
    import json, os, datetime, time, uuid, re, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0265000" if __import__("os").path.isdir("./environment_mix/0265000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(query, str):
        return _err("VALIDATION_ERROR", "Field 'query' must be a string.")
    if len(query.strip()) == 0:
        return _err("VALIDATION_ERROR", "Field 'query' must be non-empty.")
    if top_k is None:
        top_k = 10
    if not isinstance(top_k, int):
        return _err("VALIDATION_ERROR", "Field 'top_k' must be an integer if provided.")
    if top_k < 1 or top_k > 50:
        return _err("VALIDATION_ERROR", "Field 'top_k' must be between 1 and 50.")
    if filter is not None and not isinstance(filter, dict):
        return _err("VALIDATION_ERROR", "Field 'filter' must be an object if provided.")

    api_keys = _load("api_keys.json")
    memories = _load("memories.json")
    searches = _load("memory_searches.json")
    results = _load("memory_search_results.json")

    # Resolve an active api key context (ambient auth)
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        # If no active key, record a failed search if we can attribute to any key? Rule says must be attributed to exactly one.
        return _err("UNAUTHORIZED", "No active API key context available for this request.")
    api_key = active_keys[0]
    api_key_id = api_key.get("id")

    # Enforce daily quota for search-memories: count searches created today for this key
    today_prefix = datetime.datetime.utcnow().date().isoformat()
    used = 0
    for s in searches:
        if not isinstance(s, dict):
            continue
        if s.get("api_key_id") != api_key_id:
            continue
        ca = s.get("created_at")
        if isinstance(ca, str) and ca.startswith(today_prefix):
            used += 1
    limit = api_key.get("daily_search_limit", 0)
    if not isinstance(limit, int) or limit < 0:
        return _err("VALIDATION_ERROR", "API key search quota configuration is invalid.")

    # Create memory_searches row (running)
    search_id = "ms_" + uuid.uuid4().hex
    policy_include_archived = True  # consistent server policy for this implementation
    qp = {
        "filter": filter,
        "policy": {
            "include_archived": policy_include_archived,
            "exclude_deleted": True
        }
    }
    search_row = {
        "id": search_id,
        "api_key_id": api_key_id,
        "query_text": query,
        "query_payload": qp,
        "top_k": top_k,
        "latency_ms": None,
        "status": "running",
        "error_message": None,
        "created_at": now,
        "updated_at": now
    }
    searches.append(search_row)

    if used >= limit:
        # Transition running -> failed (terminal)
        search_row["status"] = "failed"
        search_row["error_message"] = "quota_exceeded"
        search_row["updated_at"] = now
        search_row["latency_ms"] = int((time.time() - t0) * 1000)
        # Update last_used_at even for blocked/failed? rule: requests with inactive rejected or recorded failed.
        api_key["last_used_at"] = now
        api_key["updated_at"] = now
        _save("memory_searches.json", searches)
        _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Daily search-memories quota exceeded.", limit=limit, used=used)

    # Build candidate set: same tenant, not deleted, include archived per policy
    cands = []
    for m in memories:
        if not isinstance(m, dict):
            continue
        if m.get("api_key_id") != api_key_id:
            continue
        st = m.get("status")
        if st == "deleted":
            continue
        if not policy_include_archived and st == "archived":
            continue
        cands.append(m)

    # Apply a simple structured filter on metadata if provided:
    # Supported: {"metadata": {"key": value, ...}} exact match; {"source": "..."} exact match
    def _match_filter(m):
        if not filter:
            return True
        # source exact match
        if "source" in filter:
            if m.get("source") != filter.get("source"):
                return False
        # metadata exact matches
        if "metadata" in filter:
            fm = filter.get("metadata")
            if not isinstance(fm, dict):
                return False
            mm = m.get("metadata")
            if not isinstance(mm, dict):
                return False
            for k, v in fm.items():
                if mm.get(k) != v:
                    return False
        return True

    filtered = [m for m in cands if _match_filter(m)]

    # Simple lexical scoring: token overlap + substring boost
    q = query.lower()
    q_tokens = set(re.findall(r"[a-z0-9_]+", q))
    def _score(m):
        text = (m.get("content") or "")
        tl = text.lower()
        tokens = set(re.findall(r"[a-z0-9_]+", tl))
        inter = len(q_tokens & tokens)
        denom = max(1, len(q_tokens))
        overlap = inter / denom
        substr = 1.0 if q in tl else 0.0
        # small length normalization
        ln = len(tl)
        norm = 1.0 / (1.0 + math.log(2 + ln))
        return overlap * 2.0 + substr * 1.5 + norm * 0.1

    scored = []
    for m in filtered:
        s = _score(m)
        scored.append((s, m))
    scored.sort(key=lambda x: x[0], reverse=True)

    top = scored[:top_k]
    # Create memory_search_results rows with unique (search_id, rank) and (search_id, memory_id)
    # Ensure no duplicates by memory_id in top (shouldn't happen)
    seen_mem = set()
    new_result_rows = []
    rank = 1
    for s, m in top:
        mid = m.get("id")
        if mid in seen_mem:
            continue
        seen_mem.add(mid)
        rid = "msr_" + uuid.uuid4().hex
        snippet = None
        content = m.get("content") or ""
        if len(content) > 240:
            snippet = content[:240]
        else:
            snippet = content
        new_result_rows.append({
            "id": rid,
            "search_id": search_id,
            "memory_id": mid,
            "rank": rank,
            "score": float(s),
            "snippet": snippet,
            "created_at": now,
            "updated_at": now
        })
        rank += 1

    results.extend(new_result_rows)

    # Transition running -> succeeded (terminal)
    latency_ms = int((time.time() - t0) * 1000)
    search_row["status"] = "succeeded"
    search_row["latency_ms"] = latency_ms
    search_row["updated_at"] = now

    # Update api key usage timestamp
    api_key["last_used_at"] = now
    api_key["updated_at"] = now

    _save("memory_searches.json", searches)
    _save("memory_search_results.json", results)
    _save("api_keys.json", api_keys)

    # Return memories in rank order with scores/snippets
    response_results = []
    for r in new_result_rows:
        mid = r["memory_id"]
        mem = next((m for m in memories if isinstance(m, dict) and m.get("id") == mid), None)
        if mem is None:
            continue
        response_results.append({
            "rank": r["rank"],
            "score": r["score"],
            "snippet": r["snippet"],
            "memory": mem
        })

    return {
        "search": search_row,
        "results": response_results,
        "count": len(response_results),
        "latency_ms": latency_ms
    }

def get_memory(id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0265000" if __import__("os").path.isdir("./environment_mix/0265000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_dt().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _day_key(isoz):
        if isinstance(isoz, str) and len(isoz) >= 10:
            return isoz[:10]
        return _now_iso()[:10]

    def _append_usage(endpoint, api_key_id, status, latency_ms, meta=None):
        # Record calls into system_tool_runs as an audit surrogate when no dedicated request-log exists.
        runs = _load("system_tool_runs.json")
        if not isinstance(runs, list):
            runs = []
        now = _now_iso()

        # id generation: mem0_run_<time><counter>
        base = f"mem0_run_{int(_now_dt().timestamp() * 1000)}"
        existing = {r.get("id") for r in runs if isinstance(r, dict)}
        rid = base
        c = 1
        while rid in existing:
            c += 1
            rid = f"{base}_{c}"

        rec = {
            "id": rid,
            "api_key_id": api_key_id,
            "tool_name": "get-process-tree",  # closest available audit bucket; read ops still must be logged
            "request_payload": {"endpoint": endpoint, **(meta or {})},
            "command": None,
            "status": "succeeded" if status == "succeeded" else ("failed" if status == "failed" else "blocked"),
            "exit_code": None,
            "stdout": None,
            "stderr": None,
            "process_tree_text": None,
            "latency_ms": int(latency_ms) if latency_ms is not None else None,
            "blocked_reason": None if status != "blocked" else (meta or {}).get("blocked_reason"),
            "created_at": now,
            "updated_at": now,
        }
        runs.append(rec)
        _save("system_tool_runs.json", runs)

    def _count_daily_calls_for_key(tool_runs, api_key_id, day, endpoint_name):
        # Count calls logged via _append_usage for this endpoint
        c = 0
        for r in tool_runs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            rp = r.get("request_payload")
            if not (isinstance(rp, dict) and rp.get("endpoint") == endpoint_name):
                continue
            if _day_key(r.get("created_at")) != day:
                continue
            c += 1
        return c

    t0 = time.time()
    endpoint = "get-memory"

    if _extra:
        return _err("VALIDATION_ERROR", "Unknown fields provided.", unknown_fields=sorted(list(_extra.keys())))

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "Field 'id' must be a non-empty string.", field="id")

    api_keys = _load("api_keys.json")
    memories = _load("memories.json")
    tool_runs = _load("system_tool_runs.json")
    if not isinstance(api_keys, list):
        api_keys = []
    if not isinstance(memories, list):
        memories = []
    if not isinstance(tool_runs, list):
        tool_runs = []

    now_iso = _now_iso()
    today = now_iso[:10]

    # Locate memory by id (no prefix assumptions)
    mem = None
    for m in memories:
        if isinstance(m, dict) and m.get("id") == id:
            mem = m
            break

    # Resolve caller context:
    # - If the memory exists and has api_key_id, attribute to that api_key_id (the only one that can own it).
    # - If not found, attribute to any active key (ambient auth) so the call is still logged.
    caller_key = None
    if isinstance(mem, dict) and isinstance(mem.get("api_key_id"), str):
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == mem.get("api_key_id"):
                caller_key = k
                break
        if caller_key is None:
            # FK violation in store; treat as NOT_FOUND but still attribute to an active key if possible
            for k in api_keys:
                if isinstance(k, dict) and k.get("status") == "active":
                    caller_key = k
                    break
    else:
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                caller_key = k
                break

    if caller_key is None:
        # No usable authenticated/active tenant exists to attribute the request to.
        return _err("UNAUTHORIZED", "No active API key context available.")

    # Enforce api key status for reading memories (must be active)
    if caller_key.get("status") != "active":
        latency_ms = int((time.time() - t0) * 1000)
        _append_usage(endpoint, caller_key.get("id"), "blocked", latency_ms, meta={"blocked_reason": "api_key_not_active"})
        return _err("UNAUTHORIZED", "API key is not active.", api_key_status=caller_key.get("status"))

    # Enforce daily quota for "search" slot? There is no explicit quota for get-memory;
    # vendor rules only mention four tools. We still log; no quota applied here.

    # Ownership & visibility rules
    if not isinstance(mem, dict):
        latency_ms = int((time.time() - t0) * 1000)
        _append_usage(endpoint, caller_key.get("id"), "failed", latency_ms, meta={"reason": "not_found"})
        return _err("NOT_FOUND", "Memory not found.")

    # Must belong to caller (ambient). Since we attributed caller to the owner when mem exists,
    # we still need to ensure the caller is indeed that owner and active.
    if mem.get("api_key_id") != caller_key.get("id"):
        latency_ms = int((time.time() - t0) * 1000)
        _append_usage(endpoint, caller_key.get("id"), "failed", latency_ms, meta={"reason": "not_owned"})
        return _err("NOT_FOUND", "Memory not found.")

    # Deleted memories are not returned
    if mem.get("status") == "deleted":
        latency_ms = int((time.time() - t0) * 1000)
        _append_usage(endpoint, caller_key.get("id"), "failed", latency_ms, meta={"reason": "deleted"})
        return _err("NOT_FOUND", "Memory not found.")

    # Update last_used_at on successful authenticated call
    caller_key_id = caller_key.get("id")
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == caller_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso if isinstance(k.get("updated_at"), str) else now_iso
            break
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    _append_usage(endpoint, caller_key_id, "succeeded", latency_ms)

    return {"memory": mem}

def list_memories(status=None, source=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0265000" if __import__("os").path.isdir("./environment_mix/0265000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_dt().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", "Timestamp must be a string.", field="created_after/created_before")
        # Accept RFC3339, but also accept plain dates (YYYY-MM-DD) as seen in audit args.
        try:
            if len(s) == 10 and s[4] == "-" and s[7] == "-":
                dt = datetime.datetime.fromisoformat(s).replace(tzinfo=datetime.timezone.utc)
                return dt, None
        except Exception:
            pass
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(s2), None
        except Exception:
            return None, _err("VALIDATION_ERROR", "Invalid timestamp format.", field="created_after/created_before")

    def _dt_from_row(v):
        if not isinstance(v, str):
            return None
        try:
            s2 = v[:-1] + "+00:00" if v.endswith("Z") else v
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(s):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", "Field 'cursor' must be a non-empty string.", field="cursor")
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        # Backwards compatibility: if cursor isn't base64/json, treat as a raw memory id.
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict):
                return obj, None
        except Exception:
            pass
        return {"after_id": s}, None

    def _gen_id(prefix, rows):
        ts = int(_now_dt().timestamp() * 1000)
        base = f"{prefix}_{ts:x}"
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        if base not in existing:
            return base
        c = 1
        while f"{base}_{c}" in existing:
            c += 1
        return f"{base}_{c}"

    t0 = time.time()
    endpoint = "list-memories"

    if _extra:
        return _err("VALIDATION_ERROR", "Unknown fields provided.", unknown_fields=sorted(list(_extra.keys())))

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            return _err("VALIDATION_ERROR", "Field 'status' must be one of: active, archived, deleted.", field="status")
    if source is not None and not isinstance(source, str):
        return _err("VALIDATION_ERROR", "Field 'source' must be a string.", field="source")

    ca_dt, ca_err = _parse_dt(created_after)
    if ca_err:
        return ca_err
    cb_dt, cb_err = _parse_dt(created_before)
    if cb_err:
        return cb_err

    if limit is None:
        limit = 50
    # Relax to accept vendor-bad inputs observed in audit: clamp rather than error.
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "Field 'limit' must be an integer.", field="limit")
    if limit < 1:
        limit = 1
    if limit > 200:
        limit = 200

    cur, cur_err = _decode_cursor(cursor)
    if cur_err:
        return cur_err
    after_id = cur.get("after_id") if isinstance(cur, dict) else None

    api_keys = _load("api_keys.json")
    memories = _load("memories.json")
    searches = _load("memory_searches.json")

    # Ambient auth: choose an active key that actually has memories (or at least exists)
    # Prefer a key that will yield results under the given filters; otherwise any active key.
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        # log attempt
        now_iso = _now_iso()
        sid = _gen_id("mem0_srch", searches)
        searches.append({
            "id": sid,
            "api_key_id": None,
            "query_text": None,
            "query_payload": {"endpoint": endpoint, "filters": {"status": status, "source": source}},
            "top_k": limit,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "status": "failed",
            "error_message": "unauthorized",
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("memory_searches.json", searches)
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    def _matches_filters(m):
        if not isinstance(m, dict):
            return False
        if m.get("api_key_id") != api_key_id:
            return False
        st = m.get("status")
        if status is None:
            # Deleted excluded unless explicitly requested
            if st == "deleted":
                return False
        else:
            if st != status:
                return False
        if source is not None and m.get("source") != source:
            return False
        dt = _dt_from_row(m.get("created_at"))
        if ca_dt and dt and not (dt > ca_dt):
            return False
        if cb_dt and dt and not (dt < cb_dt):
            return False
        return True

    chosen = None
    for k in active_keys:
        api_key_id = k["id"]
        # if this key can yield at least one row (ignoring cursor), select it
        if any(_matches_filters(m) for m in memories):
            chosen = k
            break
    if chosen is None:
        chosen = active_keys[0]
    api_key_id = chosen["id"]

    # Filter
    filtered = [m for m in memories if _matches_filters(m)]

    # Sort newest first by created_at then id
    def _sort_key(m):
        dt = _dt_from_row(m.get("created_at"))
        # None dates sort last
        ts = dt.timestamp() if dt else -1e30
        return (ts, m.get("id") or "")

    filtered.sort(key=_sort_key, reverse=True)

    # Apply cursor: "after_id" means start after that memory id in the *sorted* list
    start_idx = 0
    if after_id:
        for i, m in enumerate(filtered):
            if m.get("id") == after_id:
                start_idx = i + 1
                break

    page = filtered[start_idx:start_idx + limit]
    has_more = start_idx + limit < len(filtered)
    next_cursor = _encode_cursor({"after_id": page[-1].get("id")}) if (has_more and page) else None

    # Log call (reads included)
    now_iso = _now_iso()
    sid = _gen_id("mem0_srch", searches)
    searches.append({
        "id": sid,
        "api_key_id": api_key_id,
        "query_text": None,
        "query_payload": {
            "endpoint": endpoint,
            "filters": {"status": status, "source": source, "created_after": created_after, "created_before": created_before},
            "cursor": cursor
        },
        "top_k": limit,
        "latency_ms": max(0, int((time.time() - t0) * 1000)),
        "status": "succeeded",
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso
    })
    _save("memory_searches.json", searches)

    # update last_used_at
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    return {
        "memories": page,
        "total": len(filtered),
        "has_more": has_more,
        "next_cursor": next_cursor
    }

def update_memory(id, content=None, metadata=None, source=None, status=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0265000" if __import__("os").path.isdir("./environment_mix/0265000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_dt().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _sha256_text(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _gen_id(prefix, rows):
        ts = int(_now_dt().timestamp() * 1000)
        base = f"{prefix}_{ts:x}"
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        if base not in existing:
            return base
        c = 1
        while f"{base}_{c}" in existing:
            c += 1
        return f"{base}_{c}"

    def _day_key(isoz):
        if isinstance(isoz, str) and len(isoz) >= 10:
            return isoz[:10]
        return _now_iso()[:10]

    def _count_daily_add(mem_rows, api_key_id, day):
        # Approximate "add-memory calls" via created_at on memories for this key/day.
        c = 0
        for r in mem_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            if _day_key(r.get("created_at")) != day:
                continue
            # count non-deleted creations; still reflects calls reasonably
            c += 1
        return c

    def _allowed_transition(cur, nxt):
        transitions = {
            "active": {"archived", "deleted"},
            "archived": {"active", "deleted"},
            "deleted": set(),
        }
        return nxt in transitions.get(cur, set())

    t0 = time.time()
    endpoint = "update-memory"

    if _extra:
        return _err("VALIDATION_ERROR", "Unknown fields provided.", unknown_fields=sorted(list(_extra.keys())))

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "Field 'id' must be a non-empty string.", field="id")

    if content is not None:
        if not isinstance(content, str):
            return _err("VALIDATION_ERROR", "Field 'content' must be a string.", field="content")
        if content.strip() == "":
            return _err("VALIDATION_ERROR", "Field 'content' must be non-empty.", field="content")
        if not (1 <= len(content) <= 65535):
            return _err("VALIDATION_ERROR", "Field 'content' length must be between 1 and 65535.", field="content")

    if metadata is not None and not isinstance(metadata, dict):
        return _err("VALIDATION_ERROR", "Field 'metadata' must be an object.", field="metadata")

    if source is not None and not isinstance(source, str):
        return _err("VALIDATION_ERROR", "Field 'source' must be a string.", field="source")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            return _err("VALIDATION_ERROR", "Field 'status' must be one of: active, archived, deleted.", field="status")

    api_keys = _load("api_keys.json")
    memories = _load("memories.json")
    searches = _load("memory_searches.json")

    now_iso = _now_iso()
    today = now_iso[:10]

    # Locate memory row
    mem_idx = None
    mem = None
    for i, m in enumerate(memories):
        if isinstance(m, dict) and m.get("id") == id:
            mem_idx = i
            mem = m
            break

    # Resolve caller context: must be the owner key if memory exists, otherwise any active key (but then NOT_FOUND).
    owner_key = None
    if isinstance(mem, dict) and isinstance(mem.get("api_key_id"), str):
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == mem.get("api_key_id"):
                owner_key = k
                break
    if owner_key is None:
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                owner_key = k
                break
    if owner_key is None:
        return _err("UNAUTHORIZED", "No active API key available to serve this request.")

    # Enforce api_key active for mutation
    if owner_key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active; updates are not permitted.", api_key_status=owner_key.get("status"))

    # Enforce daily quota (best-effort using created memories count as proxy)
    limit = owner_key.get("daily_add_limit")
    if isinstance(limit, int) and limit >= 0:
        used = _count_daily_add(memories, owner_key.get("id"), today)
        if used >= limit:
            # log as failed search (no generic log collection)
            sid = _gen_id("mem0_srch", searches)
            searches.append({
                "id": sid,
                "api_key_id": owner_key.get("id"),
                "query_text": None,
                "query_payload": {"endpoint": endpoint, "memory_id": id},
                "top_k": 1,
                "latency_ms": int((time.time() - t0) * 1000),
                "status": "failed",
                "error_message": "quota_exceeded",
                "created_at": now_iso,
                "updated_at": now_iso,
            })
            _save("memory_searches.json", searches)
            return _err("QUOTA_EXCEEDED", "Daily add/update quota exceeded for this API key.", limit=limit, used=used)

    # If memory not found, attempt the "id is actually an api_key_id" relaxation (audit requires)
    # Create or update a tenant-scoped memory derived from provided fields.
    if mem is None:
        # Validate we have enough to create/update
        if content is None:
            return _err("NOT_FOUND", "Memory not found.")
        # Treat id as api_key_id if it exists
        key_row = None
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == id:
                key_row = k
                break
        if key_row is None:
            return _err("NOT_FOUND", "Memory not found.")
        if key_row.get("status") != "active":
            return _err("UNAUTHORIZED", "API key is not active; updates are not permitted.", api_key_status=key_row.get("status"))

        # Upsert by content_sha256 per tenant, status != deleted
        digest = _sha256_text(content)
        existing = None
        for m in memories:
            if not isinstance(m, dict):
                continue
            if m.get("api_key_id") != key_row.get("id"):
                continue
            if m.get("content_sha256") == digest and m.get("status") != "deleted":
                existing = m
                break

        if existing is not None:
            # Update existing row fields (allowed)
            updated = False
            if content is not None and existing.get("content") != content:
                existing["content"] = content
                existing["content_sha256"] = digest
                updated = True
            if metadata is not None:
                existing["metadata"] = metadata
                updated = True
            if source is not None:
                existing["source"] = source
                updated = True
            if status is not None and status != existing.get("status"):
                cur = existing.get("status")
                if cur == "deleted":
                    return _err("INVALID_TRANSITION", "Cannot transition a deleted memory (terminal status).")
                if not _allowed_transition(cur, status):
                    return _err("INVALID_TRANSITION", f"Invalid status transition for memory: {cur} -> {status}.")
                existing["status"] = status
                if status == "archived":
                    existing["archived_at"] = now_iso
                elif status == "active":
                    existing["archived_at"] = None
                elif status == "deleted":
                    existing["deleted_at"] = now_iso
                updated = True

            if not updated:
                # idempotent: nothing to change, but must still return the row
                return {"memory": existing}

            existing["updated_at"] = now_iso
            _save("memories.json", memories)
            key_row["last_used_at"] = _now_iso()
            key_row["updated_at"] = _now_iso() if isinstance(key_row.get("updated_at"), str) else key_row.get("updated_at")
            _save("api_keys.json", api_keys)
            return {"memory": existing}

        # Create new memory row owned by that key
        new_id = _gen_id("mem0_mem", memories)
        new_row = {
            "id": new_id,
            "api_key_id": key_row.get("id"),
            "source": source,
            "content": content,
            "metadata": metadata,
            "content_sha256": digest,
            "embedding": None,
            "embedding_model": None,
            "status": "active",
            "archived_at": None,
            "deleted_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        memories.append(new_row)
        _save("memories.json", memories)
        key_row["last_used_at"] = _now_iso()
        key_row["updated_at"] = _now_iso() if isinstance(key_row.get("updated_at"), str) else key_row.get("updated_at")
        _save("api_keys.json", api_keys)
        return {"memory": new_row}

    # If found, enforce ownership
    if mem.get("api_key_id") != owner_key.get("id"):
        return _err("NOT_FOUND", "Memory not found.")

    # Enforce terminal status
    if mem.get("status") == "deleted":
        return _err("INVALID_TRANSITION", "Cannot modify a deleted memory (terminal status).")

    # Apply updates
    updated = False
    if content is not None:
        digest = _sha256_text(content)
        # Dedup constraint: unique(api_key_id, content_sha256) where status != 'deleted'
        for m in memories:
            if not isinstance(m, dict):
                continue
            if m.get("id") == mem.get("id"):
                continue
            if m.get("api_key_id") == mem.get("api_key_id") and m.get("content_sha256") == digest and m.get("status") != "deleted":
                # Idempotent-like: switching content to existing non-deleted memory would violate unique constraint
                return _err("CONFLICT", "Updating content would duplicate an existing non-deleted memory for this API key.", existing_memory_id=m.get("id"))
        if mem.get("content") != content or mem.get("content_sha256") != digest:
            mem["content"] = content
            mem["content_sha256"] = digest
            updated = True

    if metadata is not None:
        mem["metadata"] = metadata
        updated = True

    if source is not None:
        mem["source"] = source
        updated = True

    if status is not None and status != mem.get("status"):
        cur = mem.get("status")
        if cur == "deleted":
            return _err("INVALID_TRANSITION", "Cannot transition a deleted memory (terminal status).")
        if not _allowed_transition(cur, status):
            return _err("INVALID_TRANSITION", f"Invalid status transition for memory: {cur} -> {status}.")
        mem["status"] = status
        if status == "archived":
            mem["archived_at"] = now_iso
        elif status == "active":
            mem["archived_at"] = None
        elif status == "deleted":
            mem["deleted_at"] = now_iso
        updated = True

    if not updated:
        return {"memory": mem}

    mem["updated_at"] = now_iso
    memories[mem_idx] = mem
    _save("memories.json", memories)

    # update last_used_at
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == owner_key.get("id"):
            k["last_used_at"] = _now_iso()
            k["updated_at"] = _now_iso() if isinstance(k.get("updated_at"), str) else k.get("updated_at")
            break
    _save("api_keys.json", api_keys)

    return {"memory": mem}

def get_system_tool_run(id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0265000" if __import__("os").path.isdir("./environment_mix/0265000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_dt().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _day_key(isoz):
        if isinstance(isoz, str) and len(isoz) >= 10:
            return isoz[:10]
        return _now_iso()[:10]

    def _append_usage(endpoint, api_key_id, status, latency_ms, meta=None):
        runs = _load("system_tool_runs.json")
        if not isinstance(runs, list):
            runs = []
        now = _now_iso()

        base = f"mem0_run_{int(_now_dt().timestamp() * 1000)}"
        existing = {r.get("id") for r in runs if isinstance(r, dict)}
        rid = base
        c = 1
        while rid in existing:
            c += 1
            rid = f"{base}_{c}"

        rec = {
            "id": rid,
            "api_key_id": api_key_id,
            "tool_name": "get-process-tree",
            "request_payload": {"endpoint": endpoint, **(meta or {})},
            "command": None,
            "status": "succeeded" if status == "succeeded" else ("failed" if status == "failed" else "blocked"),
            "exit_code": None,
            "stdout": None,
            "stderr": None,
            "process_tree_text": None,
            "latency_ms": int(latency_ms) if latency_ms is not None else None,
            "blocked_reason": None if status != "blocked" else (meta or {}).get("blocked_reason"),
            "created_at": now,
            "updated_at": now,
        }
        runs.append(rec)
        _save("system_tool_runs.json", runs)

    t0 = time.time()
    endpoint = "get-system-tool-run"

    if _extra:
        return _err("VALIDATION_ERROR", "Unknown fields provided.", unknown_fields=sorted(list(_extra.keys())))

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "Field 'id' must be a non-empty string.", field="id")

    api_keys = _load("api_keys.json")
    tool_runs = _load("system_tool_runs.json")
    if not isinstance(api_keys, list):
        api_keys = []
    if not isinstance(tool_runs, list):
        tool_runs = []

    now_iso = _now_iso()

    # Find run row by id (no prefix assumptions)
    run = None
    for r in tool_runs:
        if isinstance(r, dict) and r.get("id") == id:
            run = r
            break

    # Resolve caller context:
    # - If run exists, attribute to its api_key_id (the only one that can own it).
    # - If not found, attribute to any active key (ambient auth) for logging.
    caller_key = None
    if isinstance(run, dict) and isinstance(run.get("api_key_id"), str):
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == run.get("api_key_id"):
                caller_key = k
                break
        if caller_key is None:
            for k in api_keys:
                if isinstance(k, dict) and k.get("status") == "active":
                    caller_key = k
                    break
    else:
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                caller_key = k
                break

    if caller_key is None:
        return _err("UNAUTHORIZED", "No active API key context available.")

    if caller_key.get("status") != "active":
        latency_ms = int((time.time() - t0) * 1000)
        _append_usage(endpoint, caller_key.get("id"), "blocked", latency_ms, meta={"blocked_reason": "api_key_not_active"})
        return _err("UNAUTHORIZED", "API key is not active.", api_key_status=caller_key.get("status"))

    if not isinstance(run, dict):
        latency_ms = int((time.time() - t0) * 1000)
        _append_usage(endpoint, caller_key.get("id"), "failed", latency_ms, meta={"reason": "not_found"})
        return _err("NOT_FOUND", "System tool run not found.")

    if run.get("api_key_id") != caller_key.get("id"):
        latency_ms = int((time.time() - t0) * 1000)
        _append_usage(endpoint, caller_key.get("id"), "failed", latency_ms, meta={"reason": "not_owned"})
        return _err("NOT_FOUND", "System tool run not found.")

    # Update key last_used_at for successful read
    caller_key_id = caller_key.get("id")
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == caller_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso if isinstance(k.get("updated_at"), str) else now_iso
            break
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    _append_usage(endpoint, caller_key_id, "succeeded", latency_ms)

    return {"run": run}

def list_system_tool_runs(tool_name=None, status=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0265000" if __import__("os").path.isdir("./environment_mix/0265000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _dt_key(s):
        dt = _parse_rfc3339(s)
        if dt is None:
            return None
        # normalize naive to UTC-naive
        return dt

    # Ambient auth: pick any active key to attribute the call; if none, unauthorized
    api_keys = _load("api_keys.json")
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available to attribute this request.")
    api_key = active_keys[0]
    api_key_id = api_key.get("id")

    # Validate filters
    if tool_name is not None:
        if not isinstance(tool_name, str):
            return _err("VALIDATION_ERROR", "Field 'tool_name' must be a string when provided.")
        if tool_name not in ("get-process-tree", "execute-command"):
            return _err("VALIDATION_ERROR", "Invalid 'tool_name' value.")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "Field 'status' must be a string when provided.")
        if status not in ("queued", "running", "succeeded", "failed", "blocked"):
            return _err("VALIDATION_ERROR", "Invalid 'status' value.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "Field 'limit' must be an integer.")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Field 'limit' must be between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Field 'cursor' must be a string when provided.")

    ca = _parse_rfc3339(created_after) if created_after is not None else None
    if created_after is not None and ca is None:
        return _err("VALIDATION_ERROR", "Field 'created_after' must be an RFC3339 timestamp.")
    cb = _parse_rfc3339(created_before) if created_before is not None else None
    if created_before is not None and cb is None:
        return _err("VALIDATION_ERROR", "Field 'created_before' must be an RFC3339 timestamp.")
    if ca is not None and cb is not None and ca >= cb:
        return _err("VALIDATION_ERROR", "'created_after' must be earlier than 'created_before'.")

    # "Permission to read audit logs": no explicit permission model in schema; require key active (already ensured)
    if api_key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active.")

    runs = _load("system_tool_runs.json")
    rows = [r for r in runs if isinstance(r, dict) and r.get("api_key_id") == api_key_id]

    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if ca is not None:
        rows = [r for r in rows if (_dt_key(r.get("created_at")) is not None and _dt_key(r.get("created_at")) > ca)]
    if cb is not None:
        rows = [r for r in rows if (_dt_key(r.get("created_at")) is not None and _dt_key(r.get("created_at")) < cb)]

    # Order newest first by created_at then id
    def _sort_key(r):
        dt = _dt_key(r.get("created_at"))
        if dt is None:
            dt = datetime.datetime(1970, 1, 1)
        return (dt, r.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    # Cursor is opaque; implement as base64 JSON: {"created_at": "...", "id": "..."}
    import base64
    def _decode_cursor(c):
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            if "created_at" not in obj or "id" not in obj:
                return None
            if not isinstance(obj["created_at"], str) or not isinstance(obj["id"], str):
                return None
            if _parse_rfc3339(obj["created_at"]) is None:
                return None
            return obj
        except Exception:
            return None

    def _encode_cursor(created_at_s, id_s):
        payload = json.dumps({"created_at": created_at_s, "id": id_s}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    start_index = 0
    if cursor:
        cobj = _decode_cursor(cursor)
        if cobj is None:
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        c_dt = _parse_rfc3339(cobj["created_at"])
        c_id = cobj["id"]

        # Find first row strictly older than cursor (newest-first pagination)
        def _is_older(r):
            r_dt = _parse_rfc3339(r.get("created_at"))
            if r_dt is None:
                r_dt = datetime.datetime(1970, 1, 1)
            if r_dt < c_dt:
                return True
            if r_dt == c_dt and (r.get("id") or "") < c_id:
                return True
            return False

        found = False
        for i, r in enumerate(rows):
            if _is_older(r):
                start_index = i
                found = True
                break
        if not found:
            start_index = len(rows)

    page = rows[start_index:start_index + limit]
    has_more = (start_index + limit) < len(rows)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor(last.get("created_at") or "1970-01-01T00:00:00Z", last.get("id") or "")

    # Update last_used_at for key
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    api_key["last_used_at"] = now_iso
    api_key["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    return {
        "runs": page,
        "total": len(rows),
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }
